/* With GX_PALETTE_MODE_AA_TEXT_COLORS set to 16, the 8-bit palette display
   setups, rotated and not, install the 4-bit glyph draw for anti-aliased
   text, not the 3-bit one used with 8 text colors. The test creates one
   display with each setup and checks the function each installs. It checks
   which function is installed, not what that function draws. */

#include <stdio.h>
#include <stdlib.h>
#include "tx_api.h"
#include "gx_api.h"
#include "gx_system.h"
#include "gx_display.h"
#include "gx_validation_utility.h"

TEST_PARAM test_parameter = {
    "guix_8bit_palette_rotated_aa_text_colors_16_no_output", /* Test name */
    0, 0, 0, 0  /* Define the coordinates of the capture area.*/
};

int main(int argc, char ** argv)
{
    /* Start ThreadX system */
    tx_kernel_enter();
    return(0);
}

UINT gx_validation_graphics_driver_setup_8bit_palette(GX_DISPLAY *display);
UINT gx_validation_graphics_driver_setup_8bit_palette_rotated(GX_DISPLAY *display);

static UINT       failed_tests = 0;

static TX_THREAD  test_thread;
static ULONG      test_thread_stack[8192 / sizeof(ULONG)];

static GX_DISPLAY test_display;
static GX_DISPLAY test_rotated_display;

static VOID test_thread_entry(ULONG id)
{
    gx_system_initialize();

    EXPECT_EQ(16, GX_PALETTE_MODE_AA_TEXT_COLORS);

    EXPECT_EQ(GX_SUCCESS, gx_display_create(&test_display, "test_display",
                                            gx_validation_graphics_driver_setup_8bit_palette, 32, 24));
    EXPECT_EQ(GX_TRUE, test_display.gx_display_driver_4bit_glyph_draw == _gx_display_driver_8bpp_glyph_4bit_draw);

    EXPECT_EQ(GX_SUCCESS, gx_display_create(&test_rotated_display, "test_rotated_display",
                                            gx_validation_graphics_driver_setup_8bit_palette_rotated, 32, 24));
    EXPECT_EQ(GX_COLOR_FORMAT_8BIT_PALETTE, test_rotated_display.gx_display_color_format);
    EXPECT_EQ(GX_TRUE, test_rotated_display.gx_display_driver_4bit_glyph_draw == _gx_display_driver_8bpp_rotated_glyph_4bit_draw);

    if (failed_tests)
    {
        gx_validation_print_test_result(TEST_FAIL);
    }
    else
    {
        gx_validation_print_test_result(TEST_SUCCESS);
    }

    exit(failed_tests);
}

VOID tx_application_define(void *first_unused_memory)
{
    tx_thread_create(&test_thread, "test_thread", test_thread_entry, 0,
                     test_thread_stack, sizeof(test_thread_stack),
                     1, 1, TX_NO_TIME_SLICE, TX_AUTO_START);
}

